'use strict';
// Frozen verbatim from ad92acf, js/app.js core validator and js/flows.js
// nutrient whitelist/wrapper. This fixture covers these rules, not every v94 wrapper.
const meals=['Frühstück','Mittagessen','Abendessen','Snacks'];
const nutrientLabels={fiber:['Ballaststoffe','g'],vitc:['Vitamin C','mg'],iron:['Eisen','mg'],calcium:['Calcium','mg'],b12:['Vitamin B12','µg'],folate:['Folat','µg'],potassium:['Kalium','mg'],magnesium:['Magnesium','mg']};
function validNutrients(x){return x===undefined||x&&typeof x==='object'&&!Array.isArray(x)&&Object.entries(x).every(([k,v])=>['water',...Object.keys(nutrientLabels)].includes(k)&&typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=1e9)}
function validData(s){const finite=(v,min=0)=>typeof v==='number'&&Number.isFinite(v)&&v>=min;const str=x=>typeof x==='string';const day=x=>str(x)&&/^\d{4}-\d{2}-\d{2}$/.test(x);const nutrients=x=>['kcal','p','c','f'].every(k=>finite(x[k]));return s&&s.goals&&nutrients(s.goals)&&finite(s.goals.kcal,1)&&['p','c','f'].every(k=>finite(s.goals[k]))&&['foods','weights','workouts','custom'].every(k=>Array.isArray(s[k]))&&s.foods.every(x=>str(x.id)&&str(x.name)&&day(x.date)&&meals.includes(x.meal)&&finite(x.grams,.1)&&nutrients(x))&&s.weights.every(x=>str(x.id)&&day(x.date)&&finite(x.kg,20)&&x.kg<=400)&&s.custom.every(x=>str(x.id)&&str(x.name)&&nutrients(x))&&s.workouts.every(w=>str(w.id)&&str(w.name)&&day(w.date)&&typeof w.finished==='boolean'&&Array.isArray(w.exercises)&&w.exercises.every(e=>str(e.id)&&str(e.name)&&Array.isArray(e.sets)&&e.sets.every(s=>(s.kg===''||finite(s.kg))&&(s.reps===''||finite(s.reps,1))&&typeof s.done==='boolean')))}
const flowValid=validData;validData=function(s){return flowValid(s)&&s.foods.every(x=>validNutrients(x.nutrients))&&s.custom.every(x=>validNutrients(x.nutrients))&&s.workouts.every(w=>w.bodyweight===undefined||Number.isFinite(w.bodyweight)&&w.bodyweight>=20&&w.bodyweight<=400)&&(s.microGoals===undefined||validNutrients(s.microGoals))&&(s.waterGoal===undefined||Number.isFinite(s.waterGoal)&&s.waterGoal>=0&&s.waterGoal<=10000)};
module.exports = validData;
